B.bki=new A.f6("agree_roles","\ub2f4\ub2f9\uacfc \ub9c8\uac10\uc744 \ud568\uaed8 \uc815\ud55c\ub2e4","\uc544\ub9b0\uc758 \uc2e4\ud589\ub825\uc5d0 \ud50c\ub808\uc774\uc5b4\uc758 \uac00\ub2a5\ud55c \uc2dc\uac04\uc744 \ub9de\ucd98\ub2e4.","\uc88b\uc544. \ub124 \uce78\uc740 \ub124\uac00 \uc815\ud588\uc73c\ub2c8\uae4c \ub098\ub3c4 \ud568\ubd80\ub85c \uc548 \ubc14\uafc0\uac8c.",1,2,0,0)
B.bkq=new A.f6("test_small_batch","\uc18c\ub7c9\ub9cc \uba3c\uc800 \uc9c4\uc5f4\ud574 \ubc18\uc751\uc744 \ubcf8\ub2e4","\uc18d\ub3c4\ubcf4\ub2e4 \uc791\uc740 \uc2e4\ud589 \uacb0\uacfc\ub97c \uba3c\uc800 \ud655\uc778\ud55c\ub2e4.","\uc624\ucf00\uc774. \uc5f4 \uac1c\ub9cc \ud558\uace0 \uc5ec\uc12f \uc2dc\uc5d0 \uacb0\uacfc \ubcf4\uc790.",0,0,0,2)
B.bk8=new A.f6("choose_own_task","\uac01\uc790 \ub9e1\uc744 \uc77c\uc744 \uc9c1\uc811 \uace0\ub978\ub2e4","\uc9c0\uc2dc\ubcf4\ub2e4 \uacbd\uacc4\ub97c \ubd84\uba85\ud788 \ud55c \ub4a4 \ud611\ub825\ud55c\ub2e4.","\ubc18\ub300\uba74 \uc774\uc720 \ub9d0\ud574 \uc918. \uc774\ubc88\uc5d4 \ub124 \ubaab\uc744 \ub0b4\uac00 \ub300\uc2e0 \uc548 \uc815\ud560\uac8c.",0,1,1,0)
