B.bkp=new A.f6("share_assumptions","\uac01\uc790 \uc4f4 \uc804\uc81c\ub97c \ud55c \uc904\uc529 \uacf5\uac1c\ud55c\ub2e4","\uacb0\ub860\ubcf4\ub2e4 \uc0dd\uac01\uc758 \uc911\uac04 \uacfc\uc815\uc744 \ub098\ub208\ub2e4.","\ub124 \uc804\uc81c\ub294 \ub0b4\uac00 \uc548 \ub123\uc5c8\ub358 \uac70\uc57c. \ud45c\uc5d0 \ub530\ub85c \ub0a8\uaca8 \ub458\uac8c.",1,1,1,0)
