B.cfC=new A.ne(B.b7j,B.aUP,B.b2q,B.b_E,B.aVA,B.b9L,"\uac19\uc740 \ub9c8\uc74c\uc774 \uacc4\uc18d \ub4dc\ub294 \uac83 \uac19\uc544. \uc624\ub298\uc740 \uc774\uc720\ub97c \ud558\ub098\ub9cc \ub354 \uc801\uc5b4 \ubcf4\uc790.","\uc9c0\uae08\uae4c\uc9c0\ub294 \uc190\uc2e4\uc774\uc57c. \uc5b4\ub5a4 \ub3c8\uc744 \ubc88 \uac74\uc9c0 \uac19\uc774 \ubcfc\uae4c?","\uc9c0\uae08\uae4c\uc9c0\ub294 \uc218\uc775\uc774\uc57c. \ub2e4\ub978 \ub370\uc11c \uc783\uc740 \uac70\uba74 \uadf8 \ubd80\ubd84\uc744 \uc54c\ub824 \uc918.","\uc624\ub298\uc740 \uc190\ud574\ub85c \uc801\ud600 \uc788\uc5b4. \ud639\uc2dc \uc9c0\uae08\uae4c\uc9c0 \ubc88 \ub3c8\uc744 \ub9d0\ud55c \uac78\uae4c?","\uc624\ub298\uc740 \ubc8c\uc5c8\uc5b4. \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\ub77c\ub294 \ub73b\uc774\uba74 \uc54c\uaca0\uc5b4.")
B.b51=s(["\uc77d\uc5c8\uc5b4.","\uadf8\ub798, \uc54c\uaca0\uc5b4.","\ub124 \ub9d0\uc740 \ud655\uc778\ud588\uc5b4.","\ub05d\uae4c\uc9c0 \uc77d\uc5c8\uc5b4.","\uad73\uc774 \uc228\uae38 \ud544\uc694 \uc5c6\uc796\uc544.","\ub124 \ud310\ub2e8 \uacfc\uc815\uc740 \ubbff\uc5b4."],t.s)
B.b7U=s(["\uacb0\uacfc \uc548 \ub098\uc654\uc5b4. \uc9c0\uae08 \ub9d0\ud558\uba74 \uadf8\ub0e5 \ucd94\uce21\uc774\uc57c.","\uc624\ub298 \uc7a5 \uc548 \uc5f4\ub9ac\uc796\uc544. \ucef4\ud4e8\ud130 \ub044\uace0 \uc0dd\uac01\uc774\ub098 \uc815\ub9ac\ud574.","\uc6c0\uc9c1\uc784 \uac70\uc758 \uc5c6\uc5b4. \uc5b5\uc9c0\ub85c \uc758\ubbf8 \ubd99\uc774\uc9c0 \ub9c8.","\uc624\ub298\ub3c4 \ubc8c\uc5c8\uace0 \uc9c0\uae08\uae4c\uc9c0\ub3c4 \ud50c\ub7ec\uc2a4\ub124. \uc798\ub410\uc5b4.","\uc624\ub298 \ubc88 \uac74 \ubcf8\uc804\uc73c\ub85c \ub3cc\uc544\uac00\ub294 \uc911\uc778 \uac70\uc57c. \uc544\uc9c1 \ub0a8\uc558\uc5b4.","\uc624\ub298\uc740 \ube60\uc84c\uc5b4\ub3c4 \uc9c0\uae08\uae4c\uc9c0 \ubc88 \uac74 \ub0a8\uc558\uc5b4.","\uc624\ub298\ub3c4 \uc783\uc5c8\uace0 \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\ub124. \uc0b0 \ub3c8\ubd80\ud130 \uc904\uc5ec."],t.s)
B.aYX=s(["\ubb50\uac00 \uc548 \ub410\ub294\uc9c0 \uc9c1\uc811 \ud655\uc778\ud574. \uadf8\ub0e5 \uc6b4 \uc5c6\uc5c8\ub2e4\uace0 \ub118\uae30\uc9c4 \ub9d0\uace0.","\uc783\uc740 \ub3c8\ubcf4\ub2e4 \uc6d0\uc778\ubd80\ud130 \ubd10. \uc81c\ud488\uc774 \ubb38\uc81c\uc778\uc9c0 \uac00\uaca9\uc774 \ubb38\uc81c\uc778\uc9c0."],t.s)
B.b7N=s(["\ubc8c\uae34 \ud588\ub124. \uc81c\ud488\uc774 \uc9c4\uc9dc \uc88b\uc544\uc9c4 \uac74\uc9c0\ub3c4 \ubd24\uc5b4?","\uc774\ubc88\uc5d4 \ub410\uc5b4. \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ud55c \ubc88 \ub354 \ub418\ub294\uc9c0\uac00 \uc911\uc694\ud574."],t.s)
